Create the feature extraction system:

1. **Feature Extractor Interface (app/services/features.py):**
```python
from abc import ABC, abstractmethod
import numpy as np
import librosa
from pathlib import Path

class FeatureExtractor(ABC):
    @property
    @abstractmethod
    def name(self) -> str:
        """Unique name for cache directory"""
        pass

    @abstractmethod
    def extract(self, audio: np.ndarray, sr: int) -> np.ndarray:
        """Extract features, return (frames, dims) array"""
        pass

class MFCCExtractor(FeatureExtractor):
    def __init__(self, n_mfcc: int = 13, include_deltas: bool = True):
        self.n_mfcc = n_mfcc
        self.include_deltas = include_deltas

    @property
    def name(self) -> str:
        return f"mfcc_{self.n_mfcc}_{'deltas' if self.include_deltas else 'nodeltas'}"

    def extract(self, audio: np.ndarray, sr: int) -> np.ndarray:
        # Extract MFCCs
        mfcc = librosa.feature.mfcc(
            y=audio, sr=sr, n_mfcc=self.n_mfcc
        )  # (n_mfcc, frames)

        if self.include_deltas:
            delta = librosa.feature.delta(mfcc)
            delta2 = librosa.feature.delta(mfcc, order=2)
            features = np.vstack([mfcc, delta, delta2])
        else:
            features = mfcc

        # Transpose to (frames, dims)
        features = features.T

        # Per-utterance CMVN
        features = (features - features.mean(axis=0)) / (features.std(axis=0) + 1e-8)

        return features
```

2. **Feature Cache Manager:**
```python
class FeatureCache:
    def __init__(self, data_dir: str, extractor: FeatureExtractor):
        self.cache_dir = Path(data_dir) / "features" / extractor.name
        self.cache_dir.mkdir(parents=True, exist_ok=True)
        self.extractor = extractor

    def get_or_extract(self, phrase_id: str, sample_id: str,
                       audio_path: Path) -> np.ndarray:
        cache_path = self.cache_dir / phrase_id / f"{sample_id}.npy"

        if cache_path.exists():
            return np.load(cache_path)

        # Load audio and extract
        audio, sr = librosa.load(audio_path, sr=16000)
        features = self.extractor.extract(audio, sr)

        # Cache
        cache_path.parent.mkdir(parents=True, exist_ok=True)
        np.save(cache_path, features)

        return features

    def invalidate(self, phrase_id: str, sample_id: str):
        cache_path = self.cache_dir / phrase_id / f"{sample_id}.npy"
        if cache_path.exists():
            cache_path.unlink()
```

