```javascript
export class Recorder {
    constructor(options = {}) {
        this.minDuration = options.minDuration || 300;  // ms
        this.maxDuration = options.maxDuration || 10000;
        this.stream = null;
        this.mediaRecorder = null;
        this.chunks = [];
        this.startTime = null;
    }

    async requestPermission() {
        this.stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        return true;
    }

    getMimeType() {
        // Safari prefers mp4, Chrome prefers webm
        const types = ['audio/webm;codecs=opus', 'audio/webm', 'audio/mp4'];
        for (const type of types) {
            if (MediaRecorder.isTypeSupported(type)) return type;
        }
        return '';
    }

    start() {
        this.chunks = [];
        this.startTime = Date.now();

        const mimeType = this.getMimeType();
        this.mediaRecorder = new MediaRecorder(this.stream, { mimeType });

        this.mediaRecorder.ondataavailable = (e) => {
            if (e.data.size > 0) this.chunks.push(e.data);
        };

        this.mediaRecorder.start();

        // Auto-stop at max duration
        this.maxTimer = setTimeout(() => this.stop(), this.maxDuration);
    }

    async stop() {
        clearTimeout(this.maxTimer);

        const duration = Date.now() - this.startTime;
        if (duration < this.minDuration) {
            this.mediaRecorder.stop();
            throw new Error('Recording too short');
        }

        return new Promise((resolve) => {
            this.mediaRecorder.onstop = () => {
                const blob = new Blob(this.chunks, { type: this.getMimeType() });
                resolve({ blob, duration, mimeType: this.getMimeType() });
            };
            this.mediaRecorder.stop();
        });
    }
}
```

