Create the TTS system:

1. **TTS Service (app/services/tts.py):**
```python
import httpx
import hashlib
from pathlib import Path

class TTSService:
    def __init__(self, config):
        self.api_key = config.ELEVENLABS_API_KEY
        self.voice_id = config.ELEVENLABS_VOICE_ID
        self.cache_dir = Path("data/tts_cache")
        self.cache_dir.mkdir(parents=True, exist_ok=True)
        self.api_url = f"https://api.elevenlabs.io/v1/text-to-speech/{self.voice_id}"

    def _cache_key(self, text: str) -> str:
        return hashlib.sha1(f"{text}:{self.voice_id}".encode()).hexdigest()

    def get_cached(self, text: str) -> Optional[bytes]:
        cache_path = self.cache_dir / f"{self._cache_key(text)}.mp3"
        if cache_path.exists():
            return cache_path.read_bytes()
        return None

    async def synthesize(self, text: str) -> Optional[bytes]:
        # Check cache first
        cached = self.get_cached(text)
        if cached:
            return cached

        # No API key - return None for fallback
        if not self.api_key:
            return None

        try:
            async with httpx.AsyncClient() as client:
                response = await client.post(
                    self.api_url,
                    headers={
                        "xi-api-key": self.api_key,
                        "Content-Type": "application/json"
                    },
                    json={
                        "text": text,
                        "model_id": "eleven_monolingual_v1",
                        "voice_settings": {
                            "stability": 0.75,
                            "similarity_boost": 0.75
                        }
                    },
                    timeout=10.0
                )

                if response.status_code == 200:
                    audio = response.content
                    # Cache for future use
                    cache_path = self.cache_dir / f"{self._cache_key(text)}.mp3"
                    cache_path.write_bytes(audio)
                    return audio

        except (httpx.TimeoutException, httpx.NetworkError):
            pass

        return None  # Fallback to browser TTS
```

