import httpx
from fastapi import APIRouter, HTTPException

router = APIRouter(prefix="/api", tags=["send"])

@router.post("/send")
async def send_message(text: str, contact_id: str):
    # Load contact from contacts.json
    contact = get_contact(contact_id)
    if not contact:
        raise HTTPException(404, "Contact not found")

    try:
        async with httpx.AsyncClient() as client:
            response = await client.post(
                f"{settings.PHOTON_SERVICE_URL}/send",
                json={"to": contact["handle"], "text": text},
                timeout=10.0
            )

            if response.status_code == 200:
                return {"ok": True}
            else:
                return {"ok": False, "error": response.json().get("error")}
    except httpx.TimeoutException:
        raise HTTPException(504, "Photon service timeout")
    except httpx.NetworkError:
        raise HTTPException(503, "Photon service unavailable")
