export class SendButtons {
    constructor(container, contactsManager) {
        this.container = container;
        this.contacts = contactsManager;
    }

    show(text) {
        const contacts = this.contacts.getAll();

        this.container.innerHTML = `
            <div class="send-buttons">
                ${contacts.map(c => `
                    <button class="send-btn" data-contact-id="${c.id}">
                        <span class="emoji">${c.emoji || '👤'}</span>
                        <span class="name">Send to ${c.name}</span>
                    </button>
                `).join('')}
            </div>
        `;

        this.container.querySelectorAll('.send-btn').forEach(btn => {
            btn.onclick = () => this.send(text, btn.dataset.contactId, btn);
        });

        this.container.classList.remove('hidden');
    }

    async send(text, contactId, button) {
        button.disabled = true;
        button.classList.add('sending');
        button.innerHTML = '<span class="spinner"></span> Sending...';

        try {
            const res = await fetch('/api/send', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ text, contact_id: contactId })
            });

            const result = await res.json();

            if (result.ok) {
                button.classList.remove('sending');
                button.classList.add('sent');
                button.innerHTML = '✓ Sent!';
            } else {
                throw new Error(result.error);
            }
        } catch (e) {
            button.classList.remove('sending');
            button.classList.add('failed');
            button.innerHTML = '✗ Failed';
            button.disabled = false;  // Allow retry
        }
    }

    hide() {
        this.container.classList.add('hidden');
    }
}
