```python
import subprocess
import httpx
from typing import Dict, Any

class HealthChecker:
    def __init__(self, config):
        self.config = config

    async def check_all(self) -> Dict[str, Any]:
        return {
            "status": "ok",
            "checks": {
                "ffmpeg": self.check_ffmpeg(),
                "phoneme_model": self.check_phoneme_model(),
                "elevenlabs_key": self.check_elevenlabs_key(),
                "photon_service": await self.check_photon_service(),
                "disk_space": self.check_disk_space(),
            }
        }

    def check_ffmpeg(self) -> Dict[str, Any]:
        try:
            result = subprocess.run(
                ["ffmpeg", "-version"],
                capture_output=True,
                timeout=5
            )
            return {
                "ok": result.returncode == 0,
                "version": result.stdout.decode().split('\n')[0] if result.returncode == 0 else None
            }
        except (subprocess.TimeoutExpired, FileNotFoundError):
            return {"ok": False, "error": "ffmpeg not found"}

    def check_phoneme_model(self) -> Dict[str, Any]:
        # Check if model weights are downloaded
        # Placeholder until Phase 4
        return {"ok": True, "loaded": False, "note": "Phase 4"}

    def check_elevenlabs_key(self) -> Dict[str, Any]:
        has_key = bool(self.config.ELEVENLABS_API_KEY)
        return {
            "ok": True,  # Not having a key is ok (fallback exists)
            "configured": has_key
        }

    async def check_photon_service(self) -> Dict[str, Any]:
        try:
            async with httpx.AsyncClient() as client:
                response = await client.get(
                    f"{self.config.PHOTON_SERVICE_URL}/health",
                    timeout=5.0
                )
                return {
                    "ok": response.status_code == 200,
                    "reachable": True
                }
        except (httpx.TimeoutException, httpx.NetworkError):
            return {
                "ok": False,
                "reachable": False,
                "note": "iMessage sending unavailable"
            }

    def check_disk_space(self) -> Dict[str, Any]:
        import shutil
        total, used, free = shutil.disk_usage(".")
        return {
            "ok": free > 100 * 1024 * 1024,  # > 100MB free
            "free_mb": free // (1024 * 1024)
        }
